// Runs on `bun install` (postinstall). Finds every contexts/<name>/context.yaml and writes
// src/generated/contexts.ts, which imports each context's src/register.ts. The generated file
// is gitignored: adding a context never edits a shared file.
import { mkdirSync, readdirSync, existsSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';

const ROOT = resolve(import.meta.dir, '..');
const CONTEXTS = join(ROOT, 'contexts');

export function findContexts(root = CONTEXTS): string[] {
  if (!existsSync(root)) return [];
  return readdirSync(root, { withFileTypes: true })
    .filter(d => d.isDirectory() && existsSync(join(root, d.name, 'context.yaml')))
    .map(d => d.name)
    .sort();
}

export function render(names: string[]): string {
  const ident = (n: string) => `ctx_${n.replace(/[^a-zA-Z0-9]/g, '_')}`;
  const lines = [
    '// GENERATED by tools/gen.ts on `bun install`. Do not edit; not committed.',
    "import type { ContextDefinition } from '@lazytax/kernel';",
    ...names.map(n => `import ${ident(n)} from '../../contexts/${n}/src/register';`),
    '',
    'export interface GeneratedContext {',
    '  folder: string;',
    '  // biome-ignore lint/suspicious/noExplicitAny: each context has its own config type',
    '  definition: ContextDefinition<any>;',
    '}',
    '',
    'export const generatedContexts: GeneratedContext[] = [',
    ...names.map(n => `  { folder: 'contexts/${n}', definition: ${ident(n)} },`),
    '];',
    '',
  ];
  return lines.join('\n');
}

if (import.meta.main) {
  const names = findContexts();
  mkdirSync(join(ROOT, 'src/generated'), { recursive: true });
  writeFileSync(join(ROOT, 'src/generated/contexts.ts'), render(names));
  console.log(`gen: ${names.length} contexts -> src/generated/contexts.ts (${names.join(', ')})`);
}
